// Symbols for ICs and generic boxes
use svg::node::element::{Group, Line, Rectangle, Text as SvgText}; use svg::node::Text as SvgTextNode; use svg::Node; use super::{STROKE_COLOR, STROKE_WIDTH, FONT_SIZE, PIN_LENGTH, PIN_SPACING, TEXT_OFFSET_X}; use bhdl_netlist::Pin; use std::collections::HashMap; use crate::layout::Point; pub fn draw_ic_box(name: &str, width: f64, height: f64, pins: &[Pin]) -> (Group, f64, f64, HashMap<String, Point>) { let mut group = Group::new().set("stroke", STROKE_COLOR).set("stroke-width", STROKE_WIDTH).set("fill", "none"); let body = Rectangle::new().set("x", -width / 2.0).set("y", -height / 2.0).set("width", width).set("height", height).set("fill", "white"); let name_text = SvgText::new(name).set("x", 0).set("y", -height / 2.0 - 5.0).set("font-family", "monospace").set("font-size", FONT_SIZE).set("text-anchor", "middle").set("alignment-baseline", "central").set("fill", STROKE_COLOR).set("stroke", "none"); group.append(body); group.append(name_text); let pin_locations = if name.to_lowercase().contains("regulator") || name.to_lowercase().contains("ldo") { calculate_ldo_pin_locations(width, height, pins) } else { calculate_dip_pin_locations(width, height, pins) }; for pin in pins { if let Some(relative_pos) = pin_locations.get(&pin.name) { let is_vertical_pin = relative_pos.x.abs() < width / 4.0; let is_left_pin = relative_pos.x < 0.0; let is_top_pin = relative_pos.y < 0.0; let (outer_x, outer_y) = if is_vertical_pin { let outer_y = relative_pos.y + if is_top_pin { -PIN_LENGTH } else { PIN_LENGTH }; (relative_pos.x, outer_y) } else { let outer_x = relative_pos.x + if is_left_pin { -PIN_LENGTH } else { PIN_LENGTH }; (outer_x, relative_pos.y) }; let line = Line::new().set("x1", relative_pos.x).set("y1", relative_pos.y).set("x2", outer_x).set("y2", outer_y).set("stroke", STROKE_COLOR).set("stroke-width", STROKE_WIDTH); group.append(line); let pin_text = SvgText::new(&pin.name).set("x", outer_x).set("y", outer_y).set("font-family", "monospace").set("font-size", FONT_SIZE * 0.8).set("text-anchor", if is_left_pin { "end" } else { "start" }).set("alignment-baseline", "central").set("fill", STROKE_COLOR); group.append(pin_text); } } (group, width, height, pin_locations) } pub fn calculate_dip_pin_locations(_w: f64, _h: f64, _p: &[Pin]) -> HashMap<String, Point> { HashMap::new() } pub fn calculate_ldo_pin_locations(box_width: f64, box_height: f64, pins: &[Pin]) -> HashMap<String, Point> { let mut locations = HashMap::new(); let half_width = box_width / 2.0; let half_height = box_height / 2.0; for pin in pins { let point = match pin.name.to_uppercase().as_str() { "VIN" => Point::new(-half_width, 0.0), "VOUT" => Point::new(half_width, 0.0), "GND" => Point::new(0.0, half_height), "EN" => Point::new(0.0, -half_height), _ => Point::new(-half_width, 0.0), }; locations.insert(pin.name.clone(), point); } locations }
pub fn draw_voltage_regulator(pins: &[Pin]) -> (f64, f64, HashMap<String, Point>) { let width = 60.0; let height = 80.0; let pin_locations = calculate_ldo_pin_locations(width, height, pins); (width, height, pin_locations) }
